'use strict';
// mobby SDK for program background logic. Every call goes through the loopback program API;
// failures are thrown as MobbyError and never turned into success.
const crypto = require('crypto');

const SCHEMA = 'mobby.program-api/1';
const state = { port: null, credential: null, handlers: new Map() };

class MobbyError extends Error {
  constructor(code, reason, layer, effect) {
    super(`${code}: ${reason}`);
    this.name = 'MobbyError';
    this.code = code;
    this.reason = reason;
    this.layer = layer || null;
    this.effect = effect || 'none';
  }
}

const TYPES = {
  string: [(value) => typeof value === 'string', 'a string'],
  array: [Array.isArray, 'an array'],
  object: [(value) => value !== null && typeof value === 'object' && !Array.isArray(value), 'an object'],
};

function kind(value) {
  if (value === undefined || value === null) return String(value);
  if (Array.isArray(value)) return 'an array';
  return typeof value === 'object' ? 'an object' : `a ${typeof value}`;
}

/** Checks arguments before anything is sent; the error names the call's real form, since the API only sees the result. */
function expect(form, hint, args) {
  for (const [name, value, type] of args) {
    const [ok, expected] = TYPES[type];
    if (!ok(value)) throw new TypeError(`${form}: ${name} must be ${expected}, got ${kind(value)}. ${hint}`);
  }
}

function ready() {
  if (!state.port || !state.credential) throw new MobbyError('CONDITION_UNMET', 'sdk_not_started_by_mobby');
}

async function http(method, path, body, timeoutMs) {
  ready();
  const response = await fetch(`http://127.0.0.1:${state.port}${path}`, {
    method,
    headers: { Authorization: `Bearer ${state.credential}`, ...(body === undefined ? {} : { 'Content-Type': 'application/json' }) },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: AbortSignal.timeout(timeoutMs),
  });
  const text = await response.text();
  let json;
  try { json = JSON.parse(text); } catch { throw new MobbyError('FAILED', `invalid_response_${response.status}`); }
  return { status: response.status, json };
}

function failure(json) {
  const error = json.error || {};
  return new MobbyError(error.code || 'FAILED', error.reason || 'unknown', error.layer, json.effect);
}

function settle(json) {
  if (json.error) throw failure(json);
  switch (json.status) {
    case 'succeeded': return json.result === undefined ? null : json.result;
    case 'simulated': return { simulated: true };
    // A replay carries facts but not the result, which is returned only once.
    case 'accepted': throw new MobbyError('EFFECT_UNKNOWN', 'still_running', null, 'unknown');
    default: throw new MobbyError('EFFECT_UNKNOWN', json.status || 'unknown', null, json.effect || 'unknown');
  }
}

/** Looks up the original operation instead of resending it with a new request ID. */
async function recover(requestId, cause) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const { status, json } = await http('GET', `/v1/operations/${encodeURIComponent(requestId)}`, undefined, 5000);
      if (status === 404) throw new MobbyError('EFFECT_UNKNOWN', 'request_not_received', null, 'none');
      if (json.status === 'succeeded') throw new MobbyError('EFFECT_UNKNOWN', 'result_lost_after_success', null, json.effect);
      return json;
    } catch (error) {
      if (error instanceof MobbyError) throw error;
      await new Promise((resolve) => setTimeout(resolve, 200 * (attempt + 1)));
    }
  }
  throw new MobbyError('EFFECT_UNKNOWN', `connection_lost: ${cause && cause.message}`, null, 'unknown');
}

async function call(capability, args = {}, options = {}) {
  expect('call(capability, args)', "e.g. call('notify.show', { title: 'Done' })", [['capability', capability, 'string'], ['args', args, 'object']]);
  const requestId = options.requestId || crypto.randomUUID();
  const body = { schema: SCHEMA, requestId, capability, args };
  if (options.deadlineMs) body.deadlineMs = options.deadlineMs;
  let json;
  try {
    ({ json } = await http('POST', '/v1/operations', body, (options.deadlineMs || 30000) + 5000));
  } catch (error) {
    if (error instanceof MobbyError) throw error;
    json = await recover(requestId, error);
  }
  return settle(json);
}

async function get(path) {
  const { status, json } = await http('GET', path, undefined, 10000);
  if (status >= 400) throw failure(json);
  return json;
}

async function post(path, body) {
  const { status, json } = await http('POST', path, body, 10000);
  if (status >= 400) throw failure(json);
  return json;
}

function on(handler, fn) {
  if (typeof handler !== 'string' || typeof fn !== 'function') throw new TypeError('on(handler, fn) needs a name and a function');
  state.handlers.set(handler, fn);
}

function response(result) {
  // A dry run sends nothing, so there is no status or body; reading one must not look like a parse failure.
  if (result && result.simulated === true) {
    const absent = async () => { throw new MobbyError('SIMULATED', 'dry_run_has_no_response_body', 'dry_run', 'none'); };
    return { simulated: true, status: null, headers: {}, file: null, text: absent, json: absent };
  }
  return {
    status: result.status,
    headers: result.headers || {},
    file: result.file || null,
    text: async () => result.body,
    json: async () => JSON.parse(result.body),
  };
}

/**
 * A WebSocket that mobby holds for this run. Received messages wait in mobby until receive() pulls them, so a
 * handler can send a request and wait for its reply; closing, the end of the run or a revoked grant ends it.
 */
function socket(id, protocol) {
  let closed = null;
  const decode = (m) => (m.type === 'text' ? { type: 'text', text: m.text } : { type: 'binary', bytes: Buffer.from(m.base64, 'base64') });
  const self = {
    protocol,
    /** { code, reason, by: 'program' | 'peer' | 'mobby' } once the socket has ended, else null. */
    get closed() { return closed; },
    send: async (data) => {
      if (closed) throw new MobbyError('CONDITION_UNMET', 'socket_closed');
      if (typeof data === 'string') return call('net.websocket', { op: 'send', socket: id, text: data });
      if (data instanceof Uint8Array) return call('net.websocket', { op: 'send', socket: id, base64: Buffer.from(data).toString('base64') });
      throw new TypeError(`socket.send(data): data must be a string or a Uint8Array, got ${kind(data)}.`);
    },
    /** Messages received so far, waiting up to waitMs (at most 25000) for the first; [] when none came or the socket ended. */
    receive: async (options = {}) => {
      if (closed) return [];
      const waitMs = options.waitMs === undefined ? 25000 : options.waitMs;
      const result = await call('net.websocket', { op: 'receive', socket: id, waitMs }, { deadlineMs: waitMs + 10000 });
      if (result.closed) closed = result.closed;
      return result.messages.map(decode);
    },
    close: async (code = 1000, reason = '') => {
      if (closed) return closed;
      closed = (await call('net.websocket', { op: 'close', socket: id, code, reason })).closed;
      return closed;
    },
    /** for await (const message of socket) — ends when the socket closes. */
    async *[Symbol.asyncIterator]() {
      while (!closed) for (const message of await self.receive()) yield message;
    },
  };
  return self;
}

/** A dry run opens nothing: sending and closing are simulated locally, and there are no messages to read. */
function simulatedSocket() {
  const absent = async () => { throw new MobbyError('SIMULATED', 'dry_run_has_no_socket_messages', 'dry_run', 'none'); };
  return {
    simulated: true, protocol: null, closed: null,
    send: async () => ({ simulated: true }),
    receive: absent,
    close: async () => ({ code: 1000, reason: 'simulated', by: 'program' }),
    async *[Symbol.asyncIterator]() { await absent(); },
  };
}

module.exports = {
  MobbyError,
  call,
  on,
  capabilities: { list: async () => (await get('/v1/capabilities')).capabilities },
  permissions: {
    list: async () => (await get('/v1/permissions')).permissions,
    request: async (capability, scope) => {
      expect('permissions.request(capability, scope)', "e.g. permissions.request('net.http', { domains: ['api.example.com'] })", [['capability', capability, 'string']]);
      return post('/v1/permissions/requests', { capability, ...(scope ? { scope } : {}) });
    },
  },
  kv: {
    get: async (key) => { expect('kv.get(key)', "e.g. kv.get('last')", [['key', key, 'string']]); return call('storage.kv', { op: 'get', key }); },
    set: async (key, value) => { expect('kv.set(key, value)', "Arguments are positional, e.g. kv.set('last', 42)", [['key', key, 'string']]); return call('storage.kv', { op: 'set', key, value }); },
    delete: async (key) => { expect('kv.delete(key)', "e.g. kv.delete('last')", [['key', key, 'string']]); return call('storage.kv', { op: 'delete', key }); },
  },
  sql: {
    query: async (sql, params = []) => {
      expect('sql.query(sql, params)', "Arguments are positional, e.g. sql.query('SELECT * FROM t WHERE id = ?', [id])", [['sql', sql, 'string'], ['params', params, 'array']]);
      return call('storage.sql', { op: 'query', sql, params });
    },
    execute: async (sql, params = []) => {
      expect('sql.execute(sql, params)', "Arguments are positional, e.g. sql.execute('INSERT INTO t VALUES (?, ?)', [a, b])", [['sql', sql, 'string'], ['params', params, 'array']]);
      return call('storage.sql', { op: 'execute', sql, params });
    },
    transaction: async (statements) => {
      expect('sql.transaction([{sql, params}])', "e.g. sql.transaction([{ sql: 'DELETE FROM t', params: [] }])", [['statements', statements, 'array']]);
      return call('storage.sql', { op: 'transaction', statements });
    },
  },
  files: {
    read: async (path) => { expect('files.read(path)', "e.g. files.read('report.csv')", [['path', path, 'string']]); return call('storage.files', { op: 'read', path }); },
    write: async (path, text) => {
      expect('files.write(path, text)', "Arguments are positional, e.g. files.write('report.csv', text)", [['path', path, 'string'], ['text', text, 'string']]);
      return call('storage.files', { op: 'write', path, text });
    },
    list: async (dir = '') => { expect('files.list(dir)', "e.g. files.list('') for the top folder", [['dir', dir, 'string']]); return call('storage.files', { op: 'list', dir }); },
    delete: async (path) => { expect('files.delete(path)', "e.g. files.delete('report.csv')", [['path', path, 'string']]); return call('storage.files', { op: 'delete', path }); },
  },
  net: {
    fetch: async (url, init = {}) => {
      expect('net.fetch(url, {method, headers, body})', "Arguments are positional, e.g. net.fetch('https://api.example.com/x', { method: 'GET' })",
        [['url', url, 'string'], ['init', init, 'object']]);
      return response(await call('net.http', {
        url, method: init.method || 'GET', headers: init.headers || {}, ...(init.body === undefined ? {} : { body: String(init.body) }),
      }, { deadlineMs: init.deadlineMs }));
    },
    websocket: async (url, options = {}) => {
      expect('net.websocket(url, {headers, protocols})', "e.g. const ws = await net.websocket('wss://stream.example.com/feed')",
        [['url', url, 'string'], ['options', options, 'object']]);
      const opened = await call('net.websocket', {
        op: 'open', url, ...(options.headers ? { headers: options.headers } : {}), ...(options.protocols ? { protocols: options.protocols } : {}),
      }, { deadlineMs: 30000 });
      if (opened && opened.simulated === true) return simulatedSocket();
      return socket(opened.socket, opened.protocol || null);
    },
  },
  secrets: {
    put: async (name, value, options = {}) => {
      expect('secrets.put(name, value, {domains})', "Arguments are positional, e.g. secrets.put('token', value, { domains: ['api.example.com'] })",
        [['name', name, 'string'], ['value', value, 'string'], ['options', options, 'object']]);
      return call('secrets', { op: 'put', name, value, domains: options.domains || [] });
    },
    list: () => call('secrets', { op: 'list' }),
    delete: async (name) => { expect('secrets.delete(name)', "e.g. secrets.delete('token')", [['name', name, 'string']]); return call('secrets', { op: 'delete', name }); },
  },
  ai: {
    call: async (request) => {
      expect('ai.call({system, messages, maxOutputTokens})', "e.g. ai.call({ messages: [{ role: 'user', text: 'Summarize this' }] })", [['request', request, 'object']]);
      expect('ai.call({system, messages, maxOutputTokens})', "messages is a list of { role: 'user' | 'assistant', text }", [['messages', request.messages, 'array']]);
      const result = await call('ai.call', request, { deadlineMs: 120000 });
      // A dry run calls no model; reading its text must not look like an empty answer.
      if (result && result.simulated === true) {
        return Object.defineProperty({ simulated: true, model: null, usage: null }, 'text', {
          enumerable: true, get() { throw new MobbyError('SIMULATED', 'dry_run_has_no_model_reply', 'dry_run', 'none'); },
        });
      }
      return result;
    },
  },
  screen: {
    read: async (options = {}) => {
      expect('screen.read({package})', "e.g. screen.read() or screen.read({ package: 'com.example.app' })", [['options', options, 'object']]);
      return call('screen.read', options.package === undefined ? {} : { package: options.package });
    },
    click: async (packageName, target) => {
      expect('screen.click(package, target)', "Arguments are positional, e.g. screen.click('com.example.app', { text: 'Skip' })",
        [['package', packageName, 'string'], ['target', target, 'object']]);
      return call('screen.click', { package: packageName, ...target });
    },
    back: async (packageName) => { expect('screen.back(package)', "e.g. screen.back('com.example.app')", [['package', packageName, 'string']]); return call('screen.back', { package: packageName }); },
    home: async (packageName) => { expect('screen.home(package)', "e.g. screen.home('com.example.app')", [['package', packageName, 'string']]); return call('screen.home', { package: packageName }); },
  },
  config: { get: () => call('config', {}) },
  notify: {
    show: async (options) => {
      expect('notify.show({title, body, openUi})', "e.g. notify.show({ title: 'Done', body: 'Saved 3 rows' })", [['options', options, 'object']]);
      return call('notify.show', options);
    },
  },
  log: (message, data) => call('log', { message: String(message), ...(data === undefined ? {} : { data }) }),
  ui: { post: async (message) => (await post('/v1/ui/messages', { message })).delivered },
};

// Used only by runner.cjs; programs are started by mobby and do not configure the SDK themselves.
Object.defineProperty(module.exports, Symbol.for('mobby.runner'), {
  value: {
    start(port, credential) { state.port = port; state.credential = credential; },
    handler(name) { return state.handlers.get(name); },
    handlers() { return [...state.handlers.keys()]; },
  },
});
